api_sketch_typescript:
// TypeScript sketch
import { StreamingClient } from '@redwood/sdk'
const client = new StreamingClient({ apiKey: process.env.RW_KEY })
const stream = await client.startStream({ model: 'rwd-large-2', windowSize: 256 })
stream.on('data', (chunk) => {
  if (chunk.checkpointHint) {
    localStorage.setItem('resume', chunk.checkpointHint.token)
  }
})
// resume
const token = localStorage.getItem('resume')
const resumed = await client.resumeStream(token)

api_sketch_go:
// Go sketch
client := redwood.NewClient(Opts{APIKey: os.Getenv("RW_KEY")})
stream, err := client.StartStream(context.Background(), &redwood.StartStreamOpts{Model: "rwd-large-2", WindowSize: 256})
for stream.Next() {
    chunk := stream.Chunk()
    if chunk.CheckpointHint != "" {
        os.WriteFile("/var/tmp/resume_token", []byte(chunk.CheckpointHint), 0600)
    }
}
// resume
data, _ := os.ReadFile("/var/tmp/resume_token")
resumed, _ := client.ResumeStream(context.Background(), string(data))
